/*
 * relatorios-fonte-pdf.js
 * Fonte Roboto Regular (Apache License 2.0, Google) embutida como asset
 * estático do próprio projeto, em base64 — carregada via <script> local,
 * sem depender de CDN externo em tempo de execução (mesma filosofia do
 * resto do app: nenhum recurso crítico fica refém de disponibilidade de
 * terceiros na hora de gerar o PDF).
 *
 * Necessária porque as 14 fontes padrão do PDF (Helvetica/Times/Courier,
 * usadas pelo jsPDF por padrão) são limitadas ao ASCII-codepage e NÃO
 * suportam o símbolo € nem acentos (á/ã/ç/é/í/ó/ú) — confirmado na própria
 * documentação do jsPDF (github.com/parallax/jsPDF). registrarFontePdf()
 * registra esta fonte no documento e a torna a fonte ativa antes de
 * qualquer texto ser desenhado no Relatório Diário exportado.
 *
 * Origem do arquivo: fonts.gstatic.com (CDN oficial do Google Fonts),
 * baixado e convertido pra base64 uma única vez durante o desenvolvimento
 * — nenhuma rede é usada em tempo de execução pra carregar a fonte.
 */

const ROBOTO_REGULAR_BASE64_PDF ='';

/** Registra e ativa a fonte Roboto num documento jsPDF — chamar uma vez, logo após `new jspdf.jsPDF()`. */
function registrarFontePdf(doc) {
  doc.addFileToVFS('Roboto-Regular.ttf', ROBOTO_REGULAR_BASE64_PDF);
  doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
  doc.setFont('Roboto', 'normal');
}